"""Write app/src/data/photo-files.ts: a static require() for each downloaded bird photo.

The app bundler (Metro) only bundles images it can see as literal require() calls, so this
file is generated from app/src/data/photos.json. Run after fetch_photos.py.
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
credits = json.loads((ROOT / "app/src/data/photos.json").read_text(encoding="utf-8"))
lines = [
    "// Generated by pipeline/gen_photo_index.py. Do not edit by hand.",
    "/* eslint-disable */",
    "export const PHOTO_FILES: Record<string, number> = {",
]
for bid in credits:
    for ext in (".jpg", ".png"):
        if (ROOT / f"app/assets/birds/{bid}{ext}").exists():
            lines.append(f"  '{bid}': require('../../assets/birds/{bid}{ext}'),")
            break
lines.append("};")
(ROOT / "app/src/data/photo-files.ts").write_text("\n".join(lines) + "\n", encoding="utf-8")
print(f"{len(lines) - 4} photos indexed")
